export function evaluate({ inputs, time }) {
  const launchSpeed = inputs.launchSpeed ?? 4.0;
  const g = 9.8;
  const apexTime = launchSpeed / g;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * g);
  const duration = (2 * launchSpeed) / g;
  const t = Math.max(0, Math.min(time, duration));
  const v = launchSpeed - g * t;
  const h = Math.max(0, launchSpeed * t - 0.5 * g * t * t);
  const y0 = 360;
  const scale = 140;
  const ballY = y0 - h * scale;
  const ballX = 320;
  let motionLabel = "Moving up";
  if (Math.abs(v) < 0.05) {
    motionLabel = "Still for an instant";
  } else if (v < 0) {
    motionLabel = "Moving down";
  }
  const lane = sdk.panel({
    id: "lane.main",
    x: 40,
    y: 20,
    w: 560,
    h: 380,
    title: "Toss Motion",
    state: motionLabel
  });
  const axis = sdk.axis("axis.height", {
    x: 100,
    y: y0,
    length: 300,
    orientation: "y",
    min: 0,
    max: 1.5,
    ticks: [0, 0.5, 1.0, 1.5],
    label: "Height",
    unit: "m"
  });
  const guide = sdk.line("guide.launch", 100, y0, 500, y0, {
    role: "neutral",
    opacity: 0.5
  });
  const ball = sdk.circle("ball.toss", ballX, ballY, 24, {
    role: "observed"
  });
  const vecV = sdk.vector("vec.v", { x: ballX + 24, y: ballY }, {
    value: Math.abs(v),
    direction: v >= 0 ? "up" : "down",
    scale: 25,
    minLength: 12,
    label: "v",
    role: "observed"
  });
  const vecA = sdk.vector("vec.a", { x: ballX - 24, y: ballY }, {
    value: g,
    direction: "down",
    scale: 4,
    minLength: 12,
    label: "a",
    role: "warning"
  });
  const callout = sdk.callout(ballX + 60, ballY - 20, [
    motionLabel,
    "Gravity pulls down"
  ], {
    id: "callout.toss",
    role: "neutral"
  });
  const objects = [...lane, axis, guide, ball, ...vecV, ...vecA, ...callout];
  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "motionState", value: motionLabel },
        { id: "gravityState", value: "Gravity pulls down" }
      ]
    },
    quantities: {
      launchSpeed,
      gravity: g,
      apexTime,
      apexHeight,
      velocity: v,
      height: h
    }
  };
}
